const SHAPE: FormShape = {
  items: { lines: () => new FormGroup({ sku: new FormControl<string | null>(null) }) },
  dateTimes: new Set(),
  omitWhenUnset: new Set(['stock']),
};

describe('aboveZero', () => {
  it('passes a number or decimal text above zero, and an unset value', () => {
    for (const value of [1, 0.01, '19.99', null, '']) {
      expect(aboveZero(new FormControl<unknown>(value))).toBeNull();
    }
  });

  it('refuses zero, a negative and what is no number, under the min key', () => {
    for (const value of [0, '0.00', -1, '-0.5', 'abc']) {
      expect(aboveZero(new FormControl<unknown>(value))).toHaveProperty('min');
    }
  });
});

describe('form bodies', () => {
  it('leaves an unset omittable field out of the body and sends an unset nullable one as null', () => {
    const group = form();
    group.controls.name.setValue('Widget');
    expect(formValueForWire(group, SHAPE)).toEqual({ name: 'Widget', note: null, lines: [] });
    group.controls.stock.setValue(4);
    expect(formValueForWire(group, SHAPE)).toEqual({ name: 'Widget', stock: 4, note: null, lines: [] });
  });

  it('sizes a repeatable field to the value it is set to', () => {
    const group = form();
    setFormValue(group, { name: 'Widget', lines: [{ sku: 'A-1' }, { sku: 'B-2' }] }, SHAPE);
    expect(group.controls.lines.length).toBe(2);
    expect(formValueForWire(group, SHAPE)).toEqual({ name: 'Widget', note: null, lines: [{ sku: 'A-1' }, { sku: 'B-2' }] });
  });
});

describe('field errors', () => {
  it('puts a field error on the control its path names and returns the rest', () => {
    const group = form();
    setFormValue(group, { lines: [{ sku: '' }] }, SHAPE);
    const unmatched = applyFieldErrors(group, [
      { field: 'lines[0].sku', message: 'Unknown SKU', code: 'other' },
      { field: 'colour', message: 'No such field', code: '' },
    ]);
    const sku = group.controls.lines.at(0).controls.sku;
    expect(sku.errors).toEqual({ server: { message: 'Unknown SKU', code: 'other' } });
    expect(sku.touched).toBe(true);
    expect(unmatched).toEqual([{ field: 'colour', message: 'No such field', code: '' }]);
  });
});

// A message catalogue that answers each key with `<key>` so a test reads which key a text came from.
const MESSAGES = { key: (messageKey: string) => ({ text: `<${messageKey}>` }) };

function refused(code: string, message = 'The service said so') {
  const group = form();
  applyFieldErrors(group, [{ field: 'name', message, code }]);
  return group.controls.name;
}

describe('a service field error, worded by its code', () => {
  for (const [code, key] of [
    ['required', 'framework.required'],
    ['invalid', 'framework.invalid'],
  ] as const) {
    it(`shows the framework string of code ${code}, never the service's own message`, () => {
      expect(serverErrorText(refused(code), MESSAGES)).toBe(`<${key}>`);
    });
  }

  it('shows the field its own wording of a code, and the framework string for a code it does not word', () => {
    const wording = { 'invalid': 'ownInvalid' };
    expect(serverErrorText(refused('invalid'), MESSAGES, wording)).toBe('<ownInvalid>');
    expect(serverErrorText(refused('required'), MESSAGES, wording)).toBe(
      '<framework.required>',
    );
  });

  it('shows the service message for a code nothing words, and an invalid value for a code-less empty one', () => {
    expect(serverErrorText(refused('unheard-of'), MESSAGES)).toBe('The service said so');
    expect(serverErrorText(refused('', ''), MESSAGES)).toBe(
      '<framework.invalid>',
    );
  });

  it('never reads a code as a member of Object.prototype', () => {
    expect(serverErrorText(refused('constructor'), MESSAGES, {})).toBe('The service said so');
    expect(serverErrorText(refused('__proto__'), MESSAGES, {})).toBe('The service said so');
  });

  it('shows nothing on a control the service refused nothing on', () => {
    expect(serverErrorText(form().controls.name, MESSAGES)).toBeNull();
    expect(serverErrorText(null, MESSAGES)).toBeNull();
  });

  it("words the client's own check of a code the same way", () => {
    const control = new FormControl<string | null>(null, [Validators.required]);
    control.markAsTouched();
    const wording = { 'required': 'ownRequired' };
    expect(fieldErrorText(control, MESSAGES, wording)).toBe('<ownRequired>');
    expect(fieldErrorText(control, MESSAGES)).toBe('<framework.required>');
  });
});

describe("the id of a control's error text", () => {
  it("is the control's path from its form, the same on every call", () => {
    const group = form();
    setFormValue(group, { lines: [{ sku: '' }, { sku: '' }] }, SHAPE);
    expect(controlErrorId('f', group.controls.name)).toBe('f-name-error');
    expect(controlErrorId('f', group.controls.lines.at(1).controls.sku)).toBe('f-lines.1.sku-error');
    expect(controlErrorId('f', group.controls.lines.at(1).controls.sku)).toBe('f-lines.1.sku-error');
  });

  it('is none for no control', () => {
    expect(controlErrorId('f', null)).toBeNull();
    expect(controlErrorId('f', undefined)).toBeNull();
  });
});

// The comparison every client target's form edit state is held to: whether a form is dirty is
// whether its shown controls' wire value is the same value as the one it opened with.
const VALUE_CASES: readonly { readonly opened: string; readonly current: string; readonly same: boolean }[] = [
  { opened: '{"name": "Ada"}', current: '{"name": "Ada"}', same: true },
  { opened: '{"name": "Ada"}', current: '{"name": "Ada Lovelace"}', same: false },
  { opened: '{"note": null}', current: '{"note": ""}', same: true },
  { opened: '{"note": null}', current: '{}', same: true },
  { opened: '{"note": ""}', current: '{"note": "x"}', same: false },
  { opened: '{"note": "x"}', current: '{"note": ""}', same: false },
  { opened: '{"code": "007"}', current: '{"code": "7"}', same: false },
  { opened: '{"price": 1250}', current: '{"price": 1250}', same: true },
  { opened: '{"price": 1250}', current: '{"price": 1251}', same: false },
  { opened: '{"price": 12.5}', current: '{"price": 12.50}', same: true },
  { opened: '{"price": 7}', current: '{"price": "7"}', same: false },
  { opened: '{"price": 0}', current: '{"price": null}', same: false },
  { opened: '{"vip": false}', current: '{"vip": null}', same: false },
  { opened: '{"vip": false}', current: '{"vip": false}', same: true },
  { opened: '{"day": "2026-11-03"}', current: '{"day": "2026-11-03"}', same: true },
  { opened: '{"day": "2026-11-03"}', current: '{"day": "2026-11-04"}', same: false },
  { opened: '{"at": "2026-11-03T10:00:00.000Z"}', current: '{"at": "2026-11-03T10:00:00.000Z"}', same: true },
  { opened: '{"at": "2026-11-03T10:00:00.000Z"}', current: '{"at": "2026-11-03T11:00:00.000Z"}', same: false },
  { opened: '{"a": 1, "b": 2}', current: '{"b": 2, "a": 1}', same: true },
  { opened: '{"tags": ["a", "b"]}', current: '{"tags": ["a", "b"]}', same: true },
  { opened: '{"tags": ["a", "b"]}', current: '{"tags": ["b", "a"]}', same: false },
  { opened: '{"tags": ["a"]}', current: '{"tags": ["a", "b"]}', same: false },
  { opened: '{"lines": [{"sku": "x", "qty": 1}]}', current: '{"lines": [{"sku": "x", "qty": 1}]}', same: true },
  { opened: '{"lines": [{"sku": "x", "qty": 1}]}', current: '{"lines": [{"sku": "x", "qty": 2}]}', same: false },
];

describe('form edit state', () => {
  for (const { opened, current, same } of VALUE_CASES) {
    it(`reads ${opened} against ${current} as ${same ? 'the same value' : 'a changed one'}`, () => {
      expect(formValuesEqual(JSON.parse(opened), JSON.parse(current))).toBe(same);
    });
  }

  it('puts the controls back to a value and clears the messages a failed submit left', () => {
    const group = form();
    setFormValue(group, { name: 'Widget', lines: [{ sku: 'A-1' }] }, SHAPE);
    const opened = formValueForWire(group, SHAPE);
    group.controls.name.setValue('Gadget');
    applyFieldErrors(group, [{ field: 'lines[0].sku', message: 'Unknown SKU', code: 'other' }]);
    setFormValue(group, opened, SHAPE);
    resetFormState(group);
    expect(formValuesEqual(opened, formValueForWire(group, SHAPE))).toBe(true);
    expect(group.controls.lines.at(0).controls.sku.errors).toBeNull();
    expect(group.controls.lines.at(0).controls.sku.touched).toBe(false);
    expect(group.dirty).toBe(false);
  });
});
